// Build one Google search per keyword, per page, scoped to Quora with a
// site: operator. Google returns about 10 organic results per page; we page
// through for more depth.
const cfg = $('Settings').first().json;
const PAGES = 2; // pages per keyword. Each page is ~10 results. Raise for more depth.

const keywords = (cfg.keywords || '')
  .split(',').map(k => k.trim()).filter(k => k.length);

if (!keywords.length) {
  throw new Error('No keywords found. Add a comma-separated list in the Settings node, e.g. web scraping, serp api.');
}

const out = [];
for (const keyword of keywords) {
  for (let page = 1; page <= PAGES; page++) {
    out.push({ json: { keyword, location: cfg.location || '', q: 'site:quora.com ' + keyword, page } });
  }
}
return out;

// Flatten organic_results from every page into one row per Quora post.
// The SearchApi node replaces the item with the API response, so we recover the
// keyword from search_parameters.q (it echoes our site:quora.com <keyword> query).
// We keep only quora.com links and dedupe by URL within this run.
const items = $input.all();
const prefix = 'site:quora.com';
const seen = new Set();
const posts = [];

for (const item of items) {
  const res = item.json || {};
  const params = res.search_parameters || {};
  let keyword = params.q || '';
  if (keyword.toLowerCase().indexOf(prefix) === 0) {
    keyword = keyword.slice(prefix.length);
  }
  keyword = keyword.trim();

  const results = res.organic_results || [];
  for (const r of results) {
    const link = r.link || '';
    // Normalise the URL (drop query string and hash) so the same post dedupes.
    const url = link.split('#')[0].split('?')[0];
    const host = (r.domain || url).toLowerCase();
    if (host.indexOf('quora.com') === -1) continue;
    if (!url || seen.has(url)) continue;
    seen.add(url);

    posts.push({ json: {
      date: new Date().toISOString().slice(0, 10),
      keyword: keyword,
      title: r.title || '',
      snippet: r.snippet || '',
      link: url
    } });
  }
}

return posts;

// Keep only Quora posts we have not saved before. Existing rows come from the
// sheet (Get Existing Links); we compare on the normalised link so the same
// post is never appended twice, even across daily runs.
const existing = $input.all();
const seen = new Set();
for (const row of existing) {
  const j = row.json || {};
  const link = j.link || j.Link || '';
  const url = String(link).split('#')[0].split('?')[0];
  if (url) seen.add(url);
}

const posts = $('Extract Quora Posts').all();
const fresh = [];
for (const p of posts) {
  const url = (p.json && p.json.link) || '';
  if (url && !seen.has(url)) fresh.push({ json: p.json });
}

return fresh;

