// Pair each AI summary back onto its post (aligned by position with Filter New
// Posts, since the AI node emits one item per input, in order). The OpenAI
// Responses node returns the text under output[].content[].text; we read it
// defensively so other response shapes still work.
function readSummary(data) {
  if (!data) return '';
  if (Array.isArray(data.output)) {
    for (const o of data.output) {
      const parts = (o && o.content) || [];
      for (const p of parts) {
        if (p && typeof p.text === 'string' && p.text.trim()) return p.text;
      }
    }
  }
  if (typeof data.output_text === 'string') return data.output_text;
  if (typeof data.content === 'string') return data.content;
  if (data.message && typeof data.message.content === 'string') return data.message.content;
  if (typeof data.text === 'string') return data.text;
  return '';
}

const items = $input.all();
const posts = $('Filter New Posts').all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const post = (posts[i] && posts[i].json) ? Object.assign({}, posts[i].json) : {};
  const summary = readSummary(items[i].json);
  out.push({ json: {
    date: post.date || '',
    keyword: post.keyword || '',
    title: post.title || '',
    summary: String(summary).trim(),
    link: post.link || ''
  } });
}

return out;
